import { LogicWrapper, MakeLogicType, actions, kea, key, path, props, reducers } from 'kea'

export interface WorkThreadLogicProps {
    threadKey: string
}

export interface WorkOptionRef {
    stepKey: string
    optionKey: string
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface workThreadLogicValues {
    expandedOverrides: Record<string, boolean>
    openOptionRef: WorkOptionRef | null
    promptShown: boolean
    viewedStepKey: string | null
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface workThreadLogicActions {
    closeItem: () => {
        value: true
    }
    closeOption: () => {
        value: true
    }
    openOption: (
        stepKey: string,
        optionKey: string
    ) => {
        optionKey: string
        stepKey: string
    }
    setPromptShown: (shown: boolean) => {
        shown: boolean
    }
    setStepExpanded: (
        stepKey: string,
        expanded: boolean
    ) => {
        expanded: boolean
        stepKey: string
    }
    viewItem: (stepKey: string) => {
        stepKey: string
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface workThreadLogicMeta {
    key: string
}

export type workThreadLogicType = MakeLogicType<
    workThreadLogicValues,
    workThreadLogicActions,
    WorkThreadLogicProps,
    workThreadLogicMeta
>

export const workThreadLogic: LogicWrapper<workThreadLogicType> = kea<workThreadLogicType>([
    props({} as WorkThreadLogicProps),
    key((props) => props.threadKey),
    path((key) => ['layout', 'today', 'workThread', 'workThreadLogic', key]),
    actions({
        setStepExpanded: (stepKey: string, expanded: boolean) => ({ stepKey, expanded }),
        openOption: (stepKey: string, optionKey: string) => ({ stepKey, optionKey }),
        closeOption: true,
        setPromptShown: (shown: boolean) => ({ shown }),
        viewItem: (stepKey: string) => ({ stepKey }),
        closeItem: true,
    }),
    reducers({
        expandedOverrides: [
            {} as Record<string, boolean>,
            {
                setStepExpanded: (state, { stepKey, expanded }) => ({ ...state, [stepKey]: expanded }),
            },
        ],
        openOptionRef: [
            null as WorkOptionRef | null,
            {
                openOption: (_, { stepKey, optionKey }) => ({ stepKey, optionKey }),
                closeOption: () => null,
            },
        ],
        promptShown: [
            false,
            {
                setPromptShown: (_, { shown }) => shown,
                openOption: () => false,
                closeOption: () => false,
            },
        ],
        // The step, not its item: two steps can be about one item and show different facts about it.
        viewedStepKey: [
            null as string | null,
            {
                viewItem: (_, { stepKey }) => stepKey,
                closeItem: () => null,
            },
        ],
    }),
])
